    'added vitamin c': 'vitamin c',
    'add melafix': 'melafix',
    'added melafix': 'melafix',
    'add pimafix': 'pimafix',
    'added pimafix': 'pimafix',
    'add methylene blue': 'methylene blue',
    'added methylene blue': 'methylene blue',
